    thumbnailSrc: '/article-thumbs/pre-money-vs-post-money-confusion.jpg',
    thumbnailHook: "One word costs ten percent.",
    thumbnailHookEmphasis: 'ten percent',
    thumbnailMode: 'A',
    reviewerStatus: 'pending',
